        infl = QUAD[realm] if i % 3 else QUAD[realm][:1]
        souvenirs.append({"id": sid, "name": sid.replace('-', ' '), "tag": tag, "influence": infl, "motif": MOTIF.get(sid), "special": SPECIAL.get(sid), "realms": [realm]})
