phr = json.load(open(os.path.join(os.path.dirname(__file__), '..', '..', 'data', 'phrases.json')))
d = phr['diary']
lines = []
for n in range(365):
    s = d['subjects'][(n * 7) % len(d['subjects'])]; v = d['verbs'][(n * 3 + n // 10) % len(d['verbs'])]; p = d['places'][(n * 5 + n // 7) % len(d['places'])]
    lines.append(f"{s[0].upper() + s[1:]} {v} {p}.")
json.dump({"$comment": "Dream Diary: 365 placeholder fragments (generated from phrase tables until real fragments are written).", "fragments": lines}, open(os.path.join(OUT, 'diary.json'), 'w'), indent=1)
